import{_ as t,o as r,c as s,a4 as n}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"RDV & réservations","description":"Extension RDV & réservations : ce que son manifeste déclare.","frontmatter":{"title":"RDV & réservations","description":"Extension RDV & réservations : ce que son manifeste déclare."},"headers":[],"relativePath":"extensions/rdv-reservations.md","filePath":"extensions/rdv-reservations.md"}'),a={name:"extensions/rdv-reservations.md"};function o(i,e,d,c,l,u){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="rdv-reservations" tabindex="-1">RDV &amp; réservations <a class="header-anchor" href="#rdv-reservations" aria-label="Permalink to &quot;RDV &amp; réservations&quot;">​</a></h1><p>Des services réservables (permanences, équipements, salles) et le formulaire public de demande. Les créneaux libres sont calculés à la demande à partir des horaires déclarés et des réservations déjà prises ; l&#39;usager peut annuler avec son numéro de dossier, sans avoir de compte.</p><p><em>Présentation reprise de <a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#démarches-en-ligne-et-candidatures">la notice d&#39;utilisation</a>.</em></p><h2 id="en-bref" tabindex="-1">En bref <a class="header-anchor" href="#en-bref" aria-label="Permalink to &quot;En bref {#en-bref}&quot;">​</a></h2><ul><li><strong>Clé technique</strong> : <code>rdv_reservations</code>, version <code>0.1.0</code>.</li><li><strong>Pack</strong> : <a href="/teuthis-cms-distribution/extensions/packs/secteur-public-fr">Secteur public FR</a>.</li><li><strong>Installée à l&#39;installation par le profil</strong> : <a href="/teuthis-cms-distribution/installer/?profil=collectivite">Collectivité</a>.</li></ul><h2 id="apports" tabindex="-1">Ce qu&#39;elle apporte <a class="header-anchor" href="#apports" aria-label="Permalink to &quot;Ce qu&#39;elle apporte {#apports}&quot;">​</a></h2><h3 id="types-de-contenu" tabindex="-1">Types de contenu <a class="header-anchor" href="#types-de-contenu" aria-label="Permalink to &quot;Types de contenu {#types-de-contenu}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Clé</th><th>Archétype</th><th>Formulaire public</th></tr></thead><tbody><tr><td>Service réservable</td><td><code>rdv_service</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Demande de réservation</td><td><code>rdv_reservation</code></td><td><code>contenu_genere_par_formulaire</code></td><td>oui</td></tr></tbody></table><h3 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages {#messages}&quot;">​</a></h3><p>Gabarits de notification : <code>rdv_reservations.reservation.recue</code>, <code>rdv_reservations.reservation.accusee</code>, <code>rdv_reservations.reservation.annulee</code>.</p><h2 id="droits" tabindex="-1">Droits <a class="header-anchor" href="#droits" aria-label="Permalink to &quot;Droits {#droits}&quot;">​</a></h2><p><strong>Droits qu&#39;elle demande à l&#39;organisation</strong> : aucun.</p><h2 id="services-tiers" tabindex="-1">Services tiers et licences <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers et licences {#services-tiers}&quot;">​</a></h2><p>Son manifeste ne déclare <strong>aucun service tiers</strong>.</p><h2 id="donnees-personnelles" tabindex="-1">Données personnelles <a class="header-anchor" href="#donnees-personnelles" aria-label="Permalink to &quot;Données personnelles {#donnees-personnelles}&quot;">​</a></h2><p><strong>Oui</strong>, d&#39;après son manifeste :</p><ul><li><strong>Demande de réservation</strong> (<code>rdv_reservation</code>) : type de contenu déclaré comme contenant des données personnelles. Champs marqués comme personnels : Nom et prénom (<code>nom_client</code>) ; Votre courriel (<code>email_client</code>) ; Téléphone (<code>telephone_client</code>).</li></ul><h2 id="notice" tabindex="-1">Dans la notice <a class="header-anchor" href="#notice" aria-label="Permalink to &quot;Dans la notice {#notice}&quot;">​</a></h2><p><a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#démarches-en-ligne-et-candidatures">La notice d&#39;utilisation présente cette extension</a> (section 3).</p>',19)])])}const m=t(a,[["render",o]]);export{h as __pageData,m as default};
